import argparse
import asyncio
import json
import re
from datetime import datetime, timezone
from urllib.parse import urljoin

import pandas as pd
import requests
from bs4 import BeautifulSoup

TARGET_URL = "https://remoteok.com/"
USER_AGENT = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
)

FIELDS = [
    "Job Title",
    "Company Name",
    "Location/Timezone",
    "Salary Range",
    "Tech Tags",
    "Posted Date",
    "Apply URL",
    "Source URL",
]


def log(message):
    timestamp = datetime.now(timezone.utc).isoformat(timespec="seconds")
    print(f"[{timestamp}] {message}", flush=True)


def clean(value):
    if value is None or pd.isna(value) or str(value).strip().lower() in ("", "nan", "none", "null"):
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    text = str(value).replace("\xa0", " ")
    if text.strip().lower() in {"nan", "none", "null"}:
        return ""
    return re.sub(r"\s+", " ", text).strip()


def value_from_row(row, column):
    return clean(row.get(column, ""))


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def detect_anti_bot_signals(response=None, page_title="", body=""):
    signals = []
    status = getattr(response, "status_code", None)
    if status in {403, 429}:
        signals.append(f"HTTP anti-bot status: {status}")
    combined = f"{page_title}\n{body}".lower()
    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
        "verify you are human": "human-verification marker",
        "checking your browser": "browser-check marker",
    }
    for marker, description in markers.items():
        if marker in combined:
            signals.append(description)
    if body and len(body.strip()) < 500:
        signals.append("Unusually short response body")
    return signals


def parse_json_ld(soup):
    objects = []
    for script in soup.select('script[type="application/ld+json"]'):
        try:
            value = json.loads(script.string or script.get_text())
            if isinstance(value, list):
                objects.extend(value)
            else:
                objects.append(value)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
    return objects


def normalize_salary(value):
    text = clean(value)
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text)
    match = re.search(
        r"(?i)([$€£₹]|USD|EUR|GBP|INR)\s*[\d,]+(?:\.\d+)?(?:\s*[-–]\s*(?:[$€£₹]|USD|EUR|GBP|INR)?\s*[\d,]+(?:\.\d+)?)?",
        text,
    )
    if match:
        return clean(match.group(0))
    match = re.search(r"\b\d[\d,]*(?:\.\d+)?\s*[-–]\s*\d[\d,]*(?:\.\d+)?\b", text)
    return clean(match.group(0)) if match else ""


def find_salary(soup):
    for obj in parse_json_ld(soup):
        if not isinstance(obj, dict):
            continue
        offers = obj.get("offers")
        if isinstance(offers, dict):
            low = offers.get("lowPrice")
            high = offers.get("highPrice")
            currency = clean(offers.get("priceCurrency"))
            if low is not None and high is not None:
                return f"{currency} {low}-{high}".strip()
            if offers.get("price") is not None:
                return f"{currency} {offers.get('price')}".strip()
        if obj.get("@type") == "AggregateOffer":
            low = obj.get("lowPrice")
            high = obj.get("highPrice")
            currency = clean(obj.get("priceCurrency"))
            if low is not None and high is not None:
                return f"{currency} {low}-{high}".strip()
    for node in soup.select("[class*=salary], [id*=salary], [class*=compensation]"):
        salary = normalize_salary(node.get_text("\n", strip=True))
        if salary:
            return salary
    return ""


def links_text(nodes):
    return [clean(node.get_text(" ", strip=True)) for node in nodes if clean(node.get_text(" ", strip=True))]


def extract_detail_html(html, source_url):
    soup = BeautifulSoup(html, "html.parser")
    title = ""
    for selector in ["h1", "h2", ".job h1", ".job h2"]:
        node = soup.select_one(selector)
        if node and clean(node.get_text(" ", strip=True)):
            title = clean(node.get_text(" ", strip=True))
            break
    company = ""
    company_node = soup.select_one('a[href*="/company/"]')
    if company_node:
        company = clean(company_node.get_text(" ", strip=True))
    if not company:
        for obj in parse_json_ld(soup):
            if isinstance(obj, dict) and isinstance(obj.get("hiringOrganization"), dict):
                company = clean(obj["hiringOrganization"].get("name"))
                if company:
                    break
    apply_node = soup.select_one('a[href^="/l/"]')
    apply_url = urljoin(source_url, apply_node.get("href")) if apply_node else ""
    tags = links_text(soup.select('a[href*="/remote-python-jobs"], a[href*="/remote-"], a[href*="/tags/"]'))
    tags = list(dict.fromkeys(tags))
    location = ""
    location_nodes = soup.select('[class*=location], [id*=location], a[href*="/remote-jobs-in-"]')
    if location_nodes:
        location = clean("; ".join(dict.fromkeys(links_text(location_nodes))))
    body_text = clean(soup.get_text("\n", strip=True))
    if not location:
        location_match = re.search(r"(?i)location\s*[:\n]\s*([^\n]{2,100})", body_text)
        if location_match:
            location = clean(location_match.group(1))
    posted = ""
    date_match = re.search(r"\b(?:\d+\s*(?:m|h|d|w|mo|y)|today|yesterday)\b", body_text, re.I)
    if date_match:
        posted = clean(date_match.group(0))
    return {
        "Job Title": title,
        "Company Name": company,
        "Location/Timezone": location,
        "Salary Range": find_salary(soup),
        "Tech Tags": ", ".join(tags),
        "Posted Date": posted,
        "Apply URL": apply_url,
        "Source URL": source_url,
    }


def is_engineering(item):
    text = f"{item.get('Job Title', '')} {item.get('Tech Tags', '')}".lower()
    excluded = re.compile(
        r"\b(assistant|recruiter|recruiting|sales|marketing|designer|design|writer|" 
        r"customer support|virtual assistant|accountant|legal|teacher|" 
        r"operations|community manager|content)\b"
    )
    engineering = re.compile(
        r"\b(engineer|engineering|developer|development|software|devops|sre|" 
        r"backend|back-end|frontend|front-end|full[- ]stack|data scientist|" 
        r"machine learning|ml|architect|programmer|qa|test automation|sysadmin)\b"
    )
    return bool(engineering.search(text)) and not bool(excluded.search(text))


def is_expired(html):
    text = clean(BeautifulSoup(html, "html.parser").get_text(" ", strip=True)).lower()
    return bool(re.search(r"\b(expired|no longer accepting applications|job has been removed)\b", text))


def extract_listing_html(html, listing_url, keyword=""):
    soup = BeautifulSoup(html, "html.parser")
    keyword_lower = clean(keyword).lower()
    results = []
    for row in soup.select('tr.job[id^="job-"]'):
        title_node = row.select_one('a[href*="/remote-jobs/"]')
        if not title_node:
            continue
        title = clean(title_node.get_text(" ", strip=True))
        company_node = row.select_one('a[href*="/company/"]')
        company = clean(company_node.get_text(" ", strip=True)) if company_node else ""
        tag_nodes = row.select('a[href*="/remote-python-jobs"], a[href*="/remote-jobs-in-"], a[href*="/remote-"]')
        tags = list(dict.fromkeys(links_text(tag_nodes)))
        row_text = clean(row.get_text(" ", strip=True))
        if keyword_lower and keyword_lower not in f"{title} {company} {' '.join(tags)}".lower():
            continue
        if re.search(r"(?i)\b(expired|removed)\b", row_text):
            continue
        detail_url = urljoin(listing_url, title_node.get("href"))
        apply_node = row.select_one('a[href^="/l/"]')
        apply_url = urljoin(listing_url, apply_node.get("href")) if apply_node else ""
        location_nodes = row.select('a[href*="/remote-jobs-in-"]')
        posted_match = re.search(r"\b(?:\d+\s*(?:m|h|d|w|mo|y)|today|yesterday)\b", row_text, re.I)
        item = {
            "Job Title": title,
            "Company Name": company,
            "Location/Timezone": "; ".join(dict.fromkeys(links_text(location_nodes))),
            "Salary Range": "",
            "Tech Tags": ", ".join(tags),
            "Posted Date": clean(posted_match.group(0)) if posted_match else "",
            "Apply URL": apply_url,
            "Source URL": detail_url,
        }
        if is_engineering(item):
            results.append((item, detail_url))
        else:
            continue
    return results


def request_page(session, url, flags):
    try:
        response = session.get(url, timeout=30)
        body = response.text or ""
        for signal in detect_anti_bot_signals(response=response, body=body):
            flags.append({"Type": "Anti-bot", "URL": url, "Message": signal})
        response.raise_for_status()
        return body
    except Exception as exc:
        flags.append({"Type": "Error", "URL": url, "Message": str(exc)})
        return ""


async def dismiss_cookie_banner(page):
    try:
        for text in ["Accept all", "Accept", "I agree", "Allow all", "Agree", "Got it"]:
            locator = page.get_by_role("button", name=re.compile(rf"^{re.escape(text)}$", re.I)).first
            if await locator.count():
                await locator.click(timeout=1000)
                break
    except Exception:
        pass


async def browser_page_content(page, url, flags, keyword=""):
    try:
        response = await page.goto(url, wait_until="domcontentloaded", timeout=45000)
        await dismiss_cookie_banner(page)
        if keyword:
            try:
                search = page.locator('input[type="search"], input[name="search"], input[placeholder*="earch" i]').first
                if await search.count():
                    await search.fill(keyword)
                    await search.press("Enter")
                    await page.wait_for_timeout(1500)
            except Exception as exc:
                flags.append({"Type": "Low confidence", "URL": url, "Message": f"Search interaction uncertain: {exc}"})
        content = await page.content()
        title = await page.title()
        for signal in detect_anti_bot_signals(response=response, page_title=title, body=content):
            flags.append({"Type": "Anti-bot", "URL": url, "Message": signal})
        return content
    except Exception as exc:
        flags.append({"Type": "Error", "URL": url, "Message": str(exc)})
        return ""


async def browser_detail(page, url, flags):
    content = await browser_page_content(page, url, flags)
    return extract_detail_html(content, url) if content else {}


async def run(args, input_df, flags):
    session = requests.Session()
    session.headers.update({"User-Agent": USER_AGENT, "Accept-Language": "en-US,en;q=0.9"})
    results = []
    direct_details = []
    listing_jobs = []
    for _, row in input_df.iterrows():
        detail_url = value_from_row(row, "detail_url")
        listing_url = value_from_row(row, "listing_url") or TARGET_URL
        keyword = value_from_row(row, "keyword")
        if detail_url:
            direct_details.append(detail_url)
        else:
            listing_jobs.append((listing_url, keyword))

    for url in direct_details:
        log(f"Fetching independent detail page: {url}")
        html = request_page(session, url, flags)
        item = extract_detail_html(html, url) if html else {}
        if item and is_engineering(item) and not is_expired(html):
            results.append(item)
        elif item:
            flags.append({"Type": "Filtered", "URL": url, "Message": "Non-engineering or expired detail"})

    browser_needed = []
    for listing_url, keyword in listing_jobs:
        log(f"Fetching listing page: {listing_url}")
        html = request_page(session, listing_url, flags)
        found = extract_listing_html(html, listing_url, keyword) if html else []
        if found:
            listing_jobs_item = found
        else:
            listing_jobs_item = []
            browser_needed.append((listing_url, keyword))
        listing_jobs_item = listing_jobs_item[: args.max_products] if args.max_products else listing_jobs_item
        for item, detail_url in listing_jobs_item:
            detail_html = request_page(session, detail_url, flags)
            if detail_html:
                detailed = extract_detail_html(detail_html, detail_url)
                if detailed.get("Job Title"):
                    item.update({k: v for k, v in detailed.items() if v})
                if not is_expired(detail_html):
                    results.append(item)

    if browser_needed:
        log("Using Playwright because static listing extraction returned no rows or search may require rendering")
        try:
            from playwright.async_api import async_playwright
            async with async_playwright() as playwright:
                browser = await playwright.chromium.launch(
                    headless=args.headless,
                    args=["--disable-blink-features=AutomationControlled"],
                )
                context = await browser.new_context(user_agent=USER_AGENT)
                page = await context.new_page()
                for listing_url, keyword in browser_needed:
                    html = await browser_page_content(page, listing_url, flags, keyword)
                    found = extract_listing_html(html, listing_url, keyword) if html else []
                    for item, detail_url in found[: args.max_products] if args.max_products else found:
                        detailed = await browser_detail(page, detail_url, flags)
                        item.update({k: v for k, v in detailed.items() if v})
                        if detailed and is_engineering(item) and not is_expired(html):
                            results.append(item)
                await browser.close()
        except ImportError:
            flags.append({"Type": "Error", "URL": TARGET_URL, "Message": "Playwright is not installed"})
        except Exception as exc:
            flags.append({"Type": "Error", "URL": TARGET_URL, "Message": f"Browser workflow failed: {exc}"})

    deduped = []
    seen = set()
    for item in results:
        key = item.get("Source URL") or (item.get("Job Title"), item.get("Company Name"))
        if key not in seen:
            seen.add(key)
            deduped.append(item)
    return deduped[: args.max_products] if args.max_products else deduped


def main():
    parser = argparse.ArgumentParser(description="Scrape engineering jobs from Remote OK")
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    parser.add_argument("--headless", action=argparse.BooleanOptionalAction, default=True)
    args = parser.parse_args()

    log("Reading input workbook")
    try:
        input_df = pd.read_excel(args.input).fillna("")
    except FileNotFoundError:
        input_df = pd.DataFrame([{"listing_url": TARGET_URL}]).fillna("")
        log("Input workbook not found; using the default target URL")
    flags = []
    data = asyncio.run(run(args, input_df, flags))
    log(f"Writing {len(data)} extracted rows")
    output_df = pd.DataFrame(data, columns=FIELDS)
    flags_df = pd.DataFrame(flags, columns=["Type", "URL", "Message"])
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        output_df.to_excel(writer, sheet_name="Extracted Data", index=False)
        flags_df.to_excel(writer, sheet_name="Flags", index=False)
    log("Run complete")


if __name__ == "__main__":
    main()

import argparse
import asyncio
import logging
import re
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple
from urllib.parse import parse_qs, urljoin, urlparse

import pandas as pd
import requests
from bs4 import BeautifulSoup
from playwright.async_api import async_playwright

TARGET_URL = "https://news.ycombinator.com/jobs"
USER_AGENT = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
    "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
)


def log(message: str) -> None:
    print(f"[{datetime.now(timezone.utc).isoformat()}] {message}")


def clean(value: Any) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if text.lower() in {"nan", "none", "null"}:
        return ""
    return re.sub(r"\s+", " ", text).strip()


def get_proxy() -> None:
    return None


def solve_captcha(*args: Any, **kwargs: Any) -> None:
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def dismiss_cookie_banner(page: Any) -> None:
    async def _dismiss() -> None:
        patterns = ["Accept all", "Accept", "I agree", "Allow all", "Agree", "Got it"]
        for text in patterns:
            try:
                locator = page.get_by_role("button", name=re.compile(rf"^{re.escape(text)}$", re.I))
                if await locator.count():
                    await locator.first.click(timeout=1000)
                    return
            except Exception:
                pass

    return _dismiss()


def detect_anti_bot_signals(
    response: Optional[requests.Response] = None,
    page_title: str = "",
    body: str = "",
) -> List[str]:
    signals: List[str] = []
    status = response.status_code if response is not None else None
    if status in {403, 429}:
        signals.append(f"HTTP anti-bot status {status}")
    haystack = f"{page_title}\n{body}".lower()
    markers = {
        "captcha": "CAPTCHA marker",
        "cloudflare": "Cloudflare marker",
        "perimeterx": "PerimeterX marker",
        "datadome": "DataDome marker",
    }
    for marker, description in markers.items():
        if marker in haystack:
            signals.append(description)
    if body and len(body.strip()) < 200:
        signals.append("Unusually short response body")
    return signals


def model_code_from_url(url: str) -> str:
    query = parse_qs(urlparse(url).query)
    for key in ("modelCode", "sku"):
        values = query.get(key, [])
        if values and clean(values[0]):
            return clean(values[0])
    return ""


def normalize_currency(value: str) -> str:
    text = clean(value)
    match = re.search(r"(?:INR|USD|EUR|GBP)\s*[\d,]+(?:\.\d+)?|\b\d[\d,]*(?:\.\d+)?\b", text, re.I)
    return match.group(0) if match else ""


def is_external(url: str) -> bool:
    parsed = urlparse(url)
    return parsed.scheme in {"http", "https"} and parsed.netloc.lower() not in {
        "news.ycombinator.com",
        "www.news.ycombinator.com",
    }


def company_from_title(title: str) -> str:
    value = clean(title)
    value = re.split(r"\s+\((?:YC|Y Combinator)\b", value, maxsplit=1, flags=re.I)[0]
    value = re.split(r"\s+is hiring\b|\s+are hiring\b|\s+hiring\b", value, maxsplit=1, flags=re.I)[0]
    value = re.sub(r"\s+[-|:]\s*$", "", value).strip()
    return value


def location_from_text(title: str, body: str) -> str:
    text = f"{clean(title)} {clean(body)}"
    patterns = [
        r"\b(remote(?:[- ]friendly)?(?:,?\s+[^.;|]+)?|hybrid(?:,?\s+[^.;|]+)?|on[- ]site(?:,?\s+[^.;|]+)?)",
        r"\b(SF(?: and remote)?|San Francisco(?: and remote)?|New York(?: City)?|London|Berlin|Toronto)\b",
        r"\b(remote,?\s+[^.;|]+)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, re.I)
        if match:
            return clean(match.group(1))
    return ""


def keyword_matches(keyword: str, title: str, body: str) -> bool:
    keyword = clean(keyword)
    if not keyword:
        return True
    return keyword.casefold() in f"{title}\n{body}".casefold()


def age_for_row(row: Any) -> str:
    age = row.select_one(".subtext .age")
    if age:
        return clean(age.get_text(" ", strip=True))
    sibling = row.find_next_sibling("tr")
    if sibling:
        age = sibling.select_one(".subtext .age, .age")
        if age:
            return clean(age.get_text(" ", strip=True))
    return ""


def first_external_link(soup: BeautifulSoup, base_url: str) -> str:
    for anchor in soup.select("a[href]"):
        href = urljoin(base_url, anchor.get("href", ""))
        if is_external(href):
            return href
    return ""


def parse_detail(html: str, source_url: str) -> Dict[str, str]:
    soup = BeautifulSoup(html, "html.parser")
    title_node = soup.select_one("table.fatitem .titleline, .fatitem .titleline, .athing .titleline")
    title = clean(title_node.get_text(" ", strip=True)) if title_node else ""
    if not title:
        title_node = soup.select_one("title, h1")
        title = clean(title_node.get_text(" ", strip=True)) if title_node else ""
    age_node = soup.select_one(".subtext .age")
    posted = clean(age_node.get_text(" ", strip=True)) if age_node else ""
    body_node = soup.select_one(".toptext")
    body = body_node.get_text("\n", strip=True) if body_node else soup.get_text("\n", strip=True)
    application_url = first_external_link(soup, source_url)
    return {
        "Job Title": title,
        "Company Name": company_from_title(title),
        "Location / Remote Status": location_from_text(title, body),
        "Posted Time": posted,
        "Application URL": application_url,
        "Source URL": source_url,
        "_body": body,
    }


class Scraper:
    def __init__(self, headless: bool, max_products: Optional[int]) -> None:
        self.headless = headless
        self.max_products = max_products
        self.flags: List[Dict[str, str]] = []
        self.session = requests.Session()
        self.session.headers.update({"User-Agent": USER_AGENT, "Accept-Language": "en-US,en;q=0.9"})

    def flag(self, kind: str, message: str, source_url: str = "") -> None:
        self.flags.append({"Type": kind, "Message": message, "Source URL": source_url})

    def fetch(self, url: str) -> Tuple[str, bool]:
        log(f"Fetching {url}")
        try:
            response = self.session.get(url, timeout=30)
            body = response.text
            signals = detect_anti_bot_signals(response=response, body=body)
            for signal in signals:
                self.flag("Anti-bot", signal, url)
            if response.status_code >= 400:
                self.flag("HTTP error", f"HTTP status {response.status_code}", url)
                return body, False
            return body, True
        except requests.RequestException as exc:
            self.flag("Error", str(exc), url)
            return "", False

    async def browser_fetch(self, url: str) -> str:
        log(f"Using Playwright browser fallback for {url}")
        async with async_playwright() as playwright:
            browser = await playwright.chromium.launch(
                headless=self.headless,
                args=["--disable-blink-features=AutomationControlled"],
            )
            page = await browser.new_page(user_agent=USER_AGENT)
            try:
                response = await page.goto(url, wait_until="domcontentloaded", timeout=45000)
                await dismiss_cookie_banner(page)
                html = await page.content()
                title = await page.title()
                status = response.status if response else None
                signals = detect_anti_bot_signals(page_title=title, body=html)
                if status in {403, 429}:
                    signals.append(f"Browser HTTP anti-bot status {status}")
                for signal in signals:
                    self.flag("Anti-bot", signal, url)
                return html
            except Exception as exc:
                self.flag("Browser error", str(exc), url)
                return ""
            finally:
                await browser.close()

    def fetch_with_fallback(self, url: str) -> str:
        html, ok = self.fetch(url)
        if ok and html.strip():
            return html
        return asyncio.run(self.browser_fetch(url))

    def scrape_detail(self, url: str, keyword: str = "") -> Optional[Dict[str, str]]:
        html = self.fetch_with_fallback(url)
        if not html:
            return None
        item = parse_detail(html, url)
        body = item.pop("_body", "")
        if not keyword_matches(keyword, item["Job Title"], body):
            return None
        if not item["Job Title"]:
            self.flag("Low confidence", "Job title was not found", url)
        if not item["Application URL"]:
            self.flag("Low confidence", "No external application URL was found on detail page", url)
        return item

    def scrape_listing(self, listing_url: str, keyword: str = "") -> List[Dict[str, str]]:
        html = self.fetch_with_fallback(listing_url)
        if not html:
            return []
        soup = BeautifulSoup(html, "html.parser")
        results: List[Dict[str, str]] = []
        for row in soup.select("tr.athing"):
            link = row.select_one("a:first-of-type")
            if not link:
                continue
            title = clean(link.get_text(" ", strip=True))
            href = urljoin(listing_url, link.get("href", ""))
            posted = age_for_row(row)
            body = ""
            detail = None
            if href.startswith("https://news.ycombinator.com/item?") or href.startswith("http://news.ycombinator.com/item?"):
                detail = self.scrape_detail(href, keyword)
                if detail:
                    body = detail.get("Location / Remote Status", "")
            elif not keyword_matches(keyword, title, body):
                continue
            if keyword and detail is None and not keyword_matches(keyword, title, body):
                continue
            if detail:
                item = detail
                if not item["Posted Time"]:
                    item["Posted Time"] = posted
            else:
                item = {
                    "Job Title": title,
                    "Company Name": company_from_title(title),
                    "Location / Remote Status": location_from_text(title, ""),
                    "Posted Time": posted,
                    "Application URL": href if is_external(href) else "",
                    "Source URL": listing_url,
                }
                if not item["Application URL"]:
                    self.flag("Low confidence", "Listing link is not an external application URL", href)
            results.append(item)
            if self.max_products and len(results) >= self.max_products:
                break
        return results


def value_from_row(row: pd.Series, column: str) -> str:
    return clean(row[column]) if column in row.index else ""


def main() -> None:
    parser = argparse.ArgumentParser(description="Scrape Hacker News job postings")
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    parser.add_argument("--headless", action=argparse.BooleanOptionalAction, default=True)
    args = parser.parse_args()

    log("Reading input workbook")
    try:
        input_df = pd.read_excel(args.input).fillna("")
    except FileNotFoundError:
        input_df = pd.DataFrame([{"listing_url": TARGET_URL}])
    except Exception as exc:
        log(f"Input workbook error: {exc}")
        input_df = pd.DataFrame([{"listing_url": TARGET_URL}])

    scraper = Scraper(args.headless, args.max_products)
    rows: List[Dict[str, str]] = []
    if input_df.empty:
        input_df = pd.DataFrame([{"listing_url": TARGET_URL}])

    for _, input_row in input_df.iterrows():
        keyword = value_from_row(input_row, "keyword")
        detail_url = value_from_row(input_row, "detail_url")
        listing_url = value_from_row(input_row, "listing_url") or TARGET_URL
        if detail_url:
            log(f"Scraping independent detail URL {detail_url}")
            item = scraper.scrape_detail(detail_url, keyword)
            if item:
                rows.append(item)
        else:
            rows.extend(scraper.scrape_listing(listing_url, keyword))
        if args.max_products and len(rows) >= args.max_products:
            rows = rows[: args.max_products]
            break

    columns = [
        "Job Title",
        "Company Name",
        "Location / Remote Status",
        "Posted Time",
        "Application URL",
        "Source URL",
    ]
    output_df = pd.DataFrame(rows, columns=columns).fillna("")
    flags_df = pd.DataFrame(scraper.flags, columns=["Type", "Message", "Source URL"]).fillna("")
    log(f"Writing {len(output_df)} extracted rows and {len(flags_df)} flags")
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        output_df.to_excel(writer, sheet_name="Extracted Data", index=False)
        flags_df.to_excel(writer, sheet_name="Flags", index=False)
    log("Run complete")


if __name__ == "__main__":
    main()

import argparse
import asyncio
import json
import re
from datetime import datetime, timezone
from urllib.parse import parse_qs, urljoin, urlparse

import pandas as pd
import requests
from bs4 import BeautifulSoup
from playwright.async_api import async_playwright, TimeoutError as PlaywrightTimeoutError

TARGET_URL = "https://www.ikea.com/in/en/cat/home-office-desks-and-tables-20651/"
API_URL = "https://sik.search.blue.cdtapps.com/in/en/search?c=listaf&v=20250507"
USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126.0.0.0 Safari/537.36"


def log(message):
    print(f"[{datetime.now(timezone.utc).isoformat()}] {message}", flush=True)


def clean(value):
    if value is None or pd.isna(value) or str(value).strip().lower() in ("", "nan", "none", "null"):
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if text.lower() in {"nan", "none", "null"}:
        return ""
    return re.sub(r"\s+", " ", text).strip()


def value_from_row(row, key):
    return clean(row.get(key, ""))


def get_proxy():
    return None


def solve_captcha(*args, **kwargs):
    raise NotImplementedError("CAPTCHA solving is intentionally not implemented")


def detect_anti_bot_signals(response_or_page, source_url=""):
    flags = []
    if hasattr(response_or_page, "status_code"):
        status = response_or_page.status_code
        body = response_or_page.text or ""
        title = ""
        if status in (403, 429):
            flags.append({"type": "anti_bot", "message": f"HTTP status {status}", "source_url": source_url})
    else:
        status = None
        body = ""
        title = ""
    haystack = f"{title} {body}".lower()
    markers = ("captcha", "cloudflare", "perimeterx", "datadome")
    for marker in markers:
        if marker in haystack:
            flags.append({"type": "anti_bot", "message": f"Detected marker: {marker}", "source_url": source_url})
    if body and len(body.strip()) < 500:
        flags.append({"type": "low_confidence", "message": "Unusually short HTTP response body", "source_url": source_url})
    return flags


def http_session():
    session = requests.Session()
    session.headers.update({"User-Agent": USER_AGENT, "Accept-Language": "en-IN,en;q=0.9"})
    proxy = get_proxy()
    if proxy:
        session.proxies.update({"http": proxy, "https": proxy})
    return session


def extract_json_ld(soup):
    values = []
    for script in soup.select('script[type="application/ld+json"]'):
        try:
            data = json.loads(script.string or script.get_text())
            values.append(data)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
    return values


def find_model_code(url, text=""):
    match = re.search(r"(?:modelCode|sku)=([^&#]+)", url, re.I)
    if match:
        return match.group(1)
    match = re.search(r"\b\d{3}\.\d{3}\.\d{2}\b", text)
    return match.group(0) if match else ""


def clean_price(text):
    text = clean(text).replace("\xa0", " ")
    match = re.search(r"(?:Rs\.?|INR)\s*([\d,]+)", text, re.I)
    if not match:
        return ""
    digits = re.sub(r"[^\d]", "", match.group(1))
    return f"INR {digits}" if digits else ""


def dimensions_from_text(text):
    match = re.search(r"\b\d{2,4}\s*[x×]\s*\d{2,4}(?:\s*[x×]\s*\d{1,4})?\s*cm(?:\s*\([^)]*\))?", text, re.I)
    return clean(match.group(0)) if match else ""


def static_parse(url, session, flags):
    try:
        response = session.get(url, timeout=30)
        flags.extend(detect_anti_bot_signals(response, url))
        soup = BeautifulSoup(response.text, "html.parser")
        body = soup.get_text("\n", strip=True)
        heading = soup.find("h1")
        title = clean(heading.get_text(" ", strip=True) if heading else "")
        price = clean_price(body)
        return {"body": body, "title": title, "price": price, "json_ld": extract_json_ld(soup)}
    except requests.RequestException as exc:
        flags.append({"type": "error", "message": f"HTTP request failed: {exc}", "source_url": url})
        return {}


def recursive_product_nodes(value):
    found = []
    if isinstance(value, dict):
        if any(k in value for k in ("productName", "name", "price", "url")):
            found.append(value)
        for child in value.values():
            found.extend(recursive_product_nodes(child))
    elif isinstance(value, list):
        for child in value:
            found.extend(recursive_product_nodes(child))
    return found


def try_search_api(keyword, flags):
    if not keyword:
        return []
    session = http_session()
    payload = {"query": keyword, "page": 1}
    try:
        response = session.post(API_URL, json=payload, timeout=30)
        flags.extend(detect_anti_bot_signals(response, API_URL))
        if response.ok:
            data = response.json()
            return recursive_product_nodes(data)
        flags.append({"type": "low_confidence", "message": "Observed search API did not accept the assumed payload", "source_url": API_URL})
    except (requests.RequestException, ValueError) as exc:
        flags.append({"type": "low_confidence", "message": f"Search API unavailable or payload uncertain: {exc}", "source_url": API_URL})
    return []


async def dismiss_cookie_banner(page):
    try:
        for text in ("Accept all", "Accept", "I agree", "Allow all", "Agree", "Got it"):
            locator = page.get_by_role("button", name=re.compile(rf"^{re.escape(text)}$", re.I)).first
            if await locator.count() and await locator.is_visible():
                await locator.click(timeout=1000)
                break
    except Exception:
        pass


async def page_antibot_flags(page, url):
    flags = []
    try:
        title = await page.title()
        body = await page.locator("body").inner_text(timeout=3000)
        haystack = f"{title} {body}".lower()
        if len(body.strip()) < 500:
            flags.append({"type": "low_confidence", "message": "Unusually short rendered page body", "source_url": url})
        for marker in ("captcha", "cloudflare", "perimeterx", "datadome"):
            if marker in haystack:
                flags.append({"type": "anti_bot", "message": f"Detected marker: {marker}", "source_url": url})
    except Exception as exc:
        flags.append({"type": "error", "message": f"Could not inspect page for anti-bot signals: {exc}", "source_url": url})
    return flags


async def goto(page, url, flags):
    log(f"Opening {url}")
    try:
        response = await page.goto(url, wait_until="domcontentloaded", timeout=60000)
        if response and response.status in (403, 429):
            flags.append({"type": "anti_bot", "message": f"HTTP status {response.status}", "source_url": url})
        await dismiss_cookie_banner(page)
        await page.wait_for_timeout(1200)
        flags.extend(await page_antibot_flags(page, url))
        return True
    except Exception as exc:
        flags.append({"type": "error", "message": f"Navigation failed: {exc}", "source_url": url})
        return False


async def detail_record(page, url, flags):
    if not await goto(page, url, flags):
        return None
    try:
        await page.wait_for_selector("h1", timeout=15000)
    except PlaywrightTimeoutError:
        flags.append({"type": "low_confidence", "message": "Detail h1 was not rendered", "source_url": url})
    body = await page.locator("body").inner_text()
    h1 = await page.locator("h1").first.inner_text() if await page.locator("h1").count() else ""
    price = clean_price(body)
    dimensions = dimensions_from_text(body)
    name = clean(h1)
    subtitle = ""
    if name:
        parts = [clean(x) for x in re.split(r"\s+[–-]\s+", name) if clean(x)]
        if len(parts) > 1:
            name, subtitle = parts[0], parts[-1]
    colors = []
    try:
        color_section = page.get_by_text(re.compile(r"Choose colour", re.I)).first
        if await color_section.count():
            section_text = await color_section.locator("xpath=..\n").inner_text(timeout=2000)
            colors = sorted(set(re.findall(r"\b(?:white|black-brown|black|brown|beige|grey|blue|green|yellow|red)\b", section_text, re.I)))
    except Exception:
        pass
    stock = "Availability requires postal code/store check; no concrete stock result observed"
    if re.search(r"out of stock|not available", body, re.I):
        stock = "Out of stock / not available"
    record = {"Product Name": name, "Subtitle / Category": subtitle, "Price (INR)": price, "Dimensions": dimensions, "Color Options": ", ".join(colors), "In Stock Status": stock, "Product URL": url, "Source URL": url}
    if not name or not price:
        flags.append({"type": "low_confidence", "message": "Missing product name or price", "source_url": url})
    return record


async def listing_records(page, url, keyword, max_products, flags):
    if not await goto(page, url, flags):
        return []
    try:
        await page.wait_for_selector('a[href*="/in/en/p/"]', timeout=15000)
    except PlaywrightTimeoutError:
        flags.append({"type": "low_confidence", "message": "Product cards were not rendered", "source_url": url})
    anchors = page.locator('a[href*="/in/en/p/"]')
    count = await anchors.count()
    records = []
    seen = set()
    for index in range(count):
        anchor = anchors.nth(index)
        href = await anchor.get_attribute("href")
        if not href:
            continue
        product_url = urljoin(url, href)
        if product_url in seen:
            continue
        text = clean(await anchor.inner_text())
        if keyword and keyword.lower() not in text.lower():
            continue
        seen.add(product_url)
        record = await detail_record(page, product_url, flags)
        if record:
            records.append(record)
        await page.goto(url, wait_until="domcontentloaded", timeout=60000)
        await dismiss_cookie_banner(page)
        if max_products and len(records) >= max_products:
            break
    return records


async def run_async(input_df, args, flags):
    records = []
    async with async_playwright() as playwright:
        browser = await playwright.chromium.launch(headless=args.headless, args=["--disable-blink-features=AutomationControlled"])
        context = await browser.new_context(user_agent=USER_AGENT, locale="en-IN")
        page = await context.new_page()
        for _, row in input_df.iterrows():
            keyword = value_from_row(row, "keyword")
            detail_url = value_from_row(row, "detail_url")
            listing_url = value_from_row(row, "listing_url") or TARGET_URL
            if detail_url:
                record = await detail_record(page, detail_url, flags)
                if record:
                    records.append(record)
            else:
                api_nodes = try_search_api(keyword, flags)
                if api_nodes:
                    flags.append({"type": "low_confidence", "message": "API response found, but exact schema/payload was not captured; DOM extraction used for authoritative fields", "source_url": API_URL})
                records.extend(await listing_records(page, listing_url, keyword, args.max_products, flags))
            if args.max_products and len(records) >= args.max_products:
                records = records[:args.max_products]
                break
        await browser.close()
    return records


def main():
    parser = argparse.ArgumentParser(description="IKEA India desk scraper")
    parser.add_argument("--input", default="input.xlsx")
    parser.add_argument("--output", default="output.xlsx")
    parser.add_argument("--max-products", type=int, default=None)
    parser.add_argument("--headless", action=argparse.BooleanOptionalAction, default=True)
    args = parser.parse_args()
    log("Reading input workbook")
    input_df = pd.read_excel(args.input).fillna("")
    flags = []
    records = asyncio.run(run_async(input_df, args, flags))
    columns = ["Product Name", "Subtitle / Category", "Price (INR)", "Dimensions", "Color Options", "In Stock Status", "Product URL", "Source URL"]
    extracted = pd.DataFrame(records, columns=columns)
    flag_columns = ["type", "message", "source_url"]
    flag_df = pd.DataFrame(flags, columns=flag_columns)
    log(f"Writing {len(extracted)} records and {len(flag_df)} flags")
    with pd.ExcelWriter(args.output, engine="openpyxl") as writer:
        extracted.to_excel(writer, sheet_name="Extracted Data", index=False)
        flag_df.to_excel(writer, sheet_name="Flags", index=False)
    log("Finished")


if __name__ == "__main__":
    main()

import argparse
import asyncio
import json
import re
import sys
from datetime import datetime, timezone
from urllib.parse import quote, urljoin, urlparse

import pandas as pd
import requests
from bs4 import BeautifulSoup
from playwright.async_api import async_playwright

TARGET_URL = "https://www.uncommongoods.com/"
USER_AGENT = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
    "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
)
WAF_MARKERS = (
    "cloudflare turnstile",
    "just a moment...",
    "datadome",
    "perimeterx",
    "verify you are human",
)
PRICE_RE = re.compile(
    r"(?i)(?:[\$£€₹]|USD|CAD|EUR|GBP)\s*(\d{1,5}(?:[.,]\d{2})?)"
)
EMAIL_RE = re.compile(r"\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b", re.I)
PERSON_RE = re.compile(r"\b([A-Z][a-z]+)\s+([A-Z][a-z]+)\b")


def log(message):
    print(f"[{datetime.now(timezone.utc).isoformat()}] {message}", flush=True)


def sanitize_cell_value(val, max_len=32000):
    if val is None:
        return ""
    if isinstance(val, (dict, list)):
        s = json.dumps(val, ensure_ascii=False)
    else:
        s = str(val)
    if len(s) > max_len:
        return s[:max_len - 35] + "... [TRUNCATED_EXCEL_LIMIT]"
    return s


def clean(value):
    if value is None or pd.isna(value) or str(value).strip().lower() in ("", "nan", "none", "null"):
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    text = str(value).strip()
    if text.lower() in {"nan", "none", "null"}:
        return ""
    return text


def dismiss_cookie_banner(page):
    async def _dismiss():
        selectors = [
            "button:has-text('Accept')",
            "button:has-text('Accept All')",
            "button:has-text('Allow all')",
            "button:has-text('Got it')",
            "[aria-label*='accept' i]",
            "[id*='cookie' i] button",
        ]
        for selector in selectors:
            try:
                locator = page.locator(selector).first
                if await locator.is_visible(timeout=500):
                    await locator.click(timeout=1500)
                    return
            except Exception:
                continue
    return _dismiss()


def detect_anti_bot_signals(status, html):
    lowered = (html or "").lower()
    if status in {403, 429} or any(marker in lowered for marker in WAF_MARKERS):
        return "Blocked by bot protection"
    return ""


def mask_review_text(text):
    masked = EMAIL_RE.sub("***@***.***", text or "")

    def replace_name(match):
        return f"{match.group(1)[0]}*** {match.group(2)[0]}."

    return PERSON_RE.sub(replace_name, masked)


def text_of(node):
    return node.get_text("\n", strip=True) if node else ""


def first_nonempty(*values):
    for value in values:
        value = clean(value)
        if value:
            return value
    return ""


def json_objects(value):
    if isinstance(value, list):
        for item in value:
            yield from json_objects(item)
    elif isinstance(value, dict):
        yield value
        for child in value.values():
            if isinstance(child, (dict, list)):
                yield from json_objects(child)


def product_jsonld(soup):
    for script in soup.select("script[type='application/ld+json']"):
        try:
            data = json.loads(script.string or script.get_text())
        except (ValueError, TypeError):
            continue
        for obj in json_objects(data):
            kind = obj.get("@type", "")
            kinds = kind if isinstance(kind, list) else [kind]
            if any(str(item).lower() == "product" for item in kinds):
                return obj
    return {}


def canonical_url(soup, fallback):
    tag = soup.select_one("link[rel='canonical'][href]")
    return urljoin(fallback, tag.get("href")) if tag else fallback


def official_id(data):
    for key in ("sku", "productID", "mpn"):
        value = data.get(key) if isinstance(data, dict) else ""
        if isinstance(value, (dict, list)):
            continue
        if clean(value):
            return clean(value)
    return ""


def slug_id(url):
    path = urlparse(url).path.rstrip("/")
    match = re.search(r"/([^/?#]+)/?$", path)
    return match.group(1) if match else ""


def price_from_json(data):
    offers = data.get("offers", {}) if isinstance(data, dict) else {}
    if isinstance(offers, list):
        offers = offers[0] if offers else {}
    if not isinstance(offers, dict):
        return ""
    amount = clean(offers.get("price"))
    currency = clean(offers.get("priceCurrency"))
    if not amount or not currency:
        return ""
    symbols = {"USD": "$", "CAD": "CAD ", "EUR": "€", "GBP": "£", "INR": "₹"}
    prefix = symbols.get(currency.upper(), currency.upper() + " ")
    try:
        amount = f"{float(amount):.2f}"
    except ValueError:
        pass
    return prefix + amount


def price_from_buy_box(soup):
    selectors = [
        "[itemprop='price']",
        ".product-price",
        ".current-price",
        ".buy-box .price",
        ".price",
    ]
    for selector in selectors:
        for node in soup.select(selector):
            parent_classes = " ".join(node.parent.get("class", [])) if node.parent else ""
            if re.search(r"(?i)carousel|recommend|related", parent_classes):
                continue
            match = PRICE_RE.search(text_of(node))
            if match:
                raw = match.group(0).replace("\xa0", " ")
                return re.sub(r"\s+", " ", raw).strip()
    return ""


def extract_record(html, page_url, source_listing_url, mask_reviews=True):
    soup = BeautifulSoup(html, "html.parser")
    data = product_jsonld(soup)
    title = first_nonempty(data.get("name"), text_of(soup.select_one("h1")))
    product_url = canonical_url(soup, page_url)
    brand = data.get("brand", "")
    if isinstance(brand, dict):
        brand = brand.get("name", "")
    category = first_nonempty(data.get("category"), soup.select_one("[itemprop='category']"))
    if hasattr(category, "get_text"):
        category = text_of(category)
    description = first_nonempty(data.get("description"), text_of(soup.select_one("[itemprop='description']")))
    details = []
    for prop in data.get("additionalProperty", []) if isinstance(data, dict) else []:
        if isinstance(prop, dict):
            name = clean(prop.get("name"))
            value = clean(prop.get("value"))
            if name and value:
                details.append(f"{name}: {value}")
    for row in soup.select("table tr, .details tr, .specifications tr, [class*='dimension' i]"):
        value = text_of(row)
        if value and not re.search(r"(?i)review|rating", value):
            details.append(value)
    review_text = " ".join(text_of(node) for node in soup.select("[class*='review' i], [id*='review' i]"))
    if mask_reviews and review_text:
        review_text = mask_review_text(review_text)
    price = price_from_json(data) or price_from_buy_box(soup)
    record = {
        "product_id": "",
        "_official_id": official_id(data),
        "_slug_id": slug_id(product_url),
        "product_url": product_url,
        "source_listing_url": source_listing_url,
        "title": title,
        "price": price,
        "brand": clean(brand),
        "category": clean(category),
        "description": description,
        "details_and_dimensions": "\n".join(dict.fromkeys(details)),
    }
    if review_text and not record["details_and_dimensions"]:
        record["details_and_dimensions"] = review_text
    return record if title or data else None


def http_get(url, session):
    try:
        response = session.get(url, timeout=25)
